import React from 'react';
import ReactPlayer from 'react-player'

const ShortVideos = ({reels}) => {
  return (
    <div className='socialmedia-container-mobile'>
              {
                reels.map((reelVideo, index)=> (
                  <a href={reelVideo.redirectLink} target='_blank'
                  key={index}
                  className={'socialmedia-card-01 group'+' down'}>
                    <div className='opacity-0 overlay'>
                      <div style={{ backgroundImage: `url(${reelVideo.logo})` }} className={'video-logo _3 '+reelVideo.dimension}> </div>
                      <div className='dark-bg'> </div>
                    </div>
                    <div className='videobg1 w-background-video w-background-video-atom'>
                      <ReactPlayer playing muted loop url={[reelVideo.data.mp4, reelVideo.data.webm]} width={'100%'} height={'100%'} playsinline
                      config={{
                        file: {
                          forceVideo: true
                        }
                      }}>
                        {/* <source src={reelVideo.data} type='video/mp4'></source> */}
                      </ReactPlayer>
                    </div>
                  </a>
                ))
              }
    </div>
  )
};

export default ShortVideos;
